const tasks = [];
let uiBlocked = false;

function heavyTask(name) {
  uiBlocked = true;
  let result = 0;
  for (let i = 0; i < 5; i++) {
    result += i;
  }
  tasks.push({ name: name, result: result });
  uiBlocked = false;
  return result;
}

const result1 = heavyTask('Task A');
const result2 = heavyTask('Task B');
const total = result1 + result2;

console.log(tasks);
console.log(total);
